286 :           transformation.addAlias(name, qualifiedName);
287 :           // Bleeding functions already get a BAD_PARAMETERS error, so just
288 :           // do nothing.
289 :           // Parameters of the scope function also get a BAD_PARAMETERS
290 :           // error.
291 :         } else {
